SELECT hd.hd_buy_potential, cr.cr_reason_sk, SUM(cr.cr_return_amount) AS total_return_amount, COUNT(DISTINCT ws.ws_order_number) AS distinct_orders FROM catalog_returns cr JOIN household_demographics hd ON cr.cr_refunded_hdemo_sk = hd.hd_demo_sk JOIN web_sales ws ON ws.ws_bill_hdemo_sk = hd.hd_demo_sk WHERE hd.hd_income_band_sk = 12 AND ws.ws_sold_date_sk BETWEEN 2451118 AND 2451142 GROUP BY hd.hd_buy_potential, cr.cr_reason_sk
